// Generated by `just generate` from `src/plugins/dotclaude/slices/handoff/adapters/mod.ts`. Edit the source and run `just generate`.
// The mod handlers of the `handoff` slice. Every handler makes no model call, so `requests` is 0.
//
// `turn.step` keeps the context and the turn count of each subagent.
// `tool.call` adds the report-now note to the result of a subagent that nears a bound.
// The same `tool.call` handler sets the trigger when a package goes to `done`.
// `skill.prompt` starts the handoff of `/handoff`.
// `turn.complete` runs the handoff: it checks the triggers, submits the write prompt,
// and then, on the next `turn.complete`, runs `/clear` and submits the resume prompt.
//
// The slice keeps its flow state in this module, not in `state.json` and not in the store.
//
// `claude plugin validate` follows `$` only into a function of one file.
// For this reason, each function that touches `$` is here, and the rules are in `domain/`.

import type {
  EngineInterface,
  PluginOptions,
  ToolCallInput,
  ToolCallResult,
} from "claude-code";
import type { Handler } from "../../../kernel/slice.ts";
import {
  type AgentState,
  contextTokens,
  reportNote,
} from "../domain/context.ts";
import {
  manualHint,
  REASON_LANE,
  reasonContext,
  resumeText,
  writePrompt,
} from "../domain/text.ts";
import { isLaneDone, overContext, parseHandover } from "../domain/trigger.ts";
import { CONTEXT_PERCENT } from "../limits.ts";

/** The state of each subagent by its `agentId`. */
const agents = new Map<string, AgentState>();

/** The `userConfig` values of the plugin, which the generated `register` gives to `keepOptions`. */
let options: PluginOptions = {};

/** The reason of a trigger that fired and has no handoff yet, or undefined. */
let wanted: string | undefined;

/** The handoff file that Claude was asked to write, or undefined. */
let pending: { readonly file: string } | undefined;

/** Whether the `manual` hint went to the user for the trigger that is still active. */
let hinted = false;

/** Keeps the `userConfig` values of the plugin for the handlers. */
export const keepOptions = (values: PluginOptions): void => {
  options = values;
};

/** Forgets the flow state. A test calls it between runs. */
export const resetState = (): void => {
  agents.clear();
  wanted = undefined;
  pending = undefined;
  hinted = false;
  options = {};
};

/** Runs the CLI `bin/<name>` of this plugin and gives its status and text. */
const runBin = async (
  $: EngineInterface,
  name: string,
  args: string[],
): Promise<{ ok: boolean; text: string }> => {
  const run = await $.process.run([
    "bun",
    "--no-env-file",
    `${$.plugin.root}/bin/${name}`,
    ...args,
  ]);
  return { ok: run.exitCode === 0, text: run.stdout.trim() };
};

/** The usage of each subagent step: its context, its model, and its turn count. */
export const onTurnStep: Handler<"turn.step"> = async function* (_$, e, next) {
  const result = yield* next(e);
  if (e.agentId && result.usage) {
    const before = agents.get(e.agentId);
    agents.set(e.agentId, {
      tokens: contextTokens(result.usage),
      model: result.usage.model,
      turns: (before?.turns ?? 0) + 1,
    });
  }
  return result;
};

/** Sets the trigger when `dotclaude-spec lane <package> done` succeeds in the main session. */
const laneDone = (e: ToolCallInput, out: ToolCallResult): boolean =>
  e.tool === "Bash" &&
  !e.agentId &&
  out.deny === undefined &&
  !out.isError &&
  isLaneDone(e.command);

/** Adds the report-now note to the result of a tool call of a subagent that nears a bound, and watches for a package that goes to `done`. */
export const onToolCall: Handler<"tool.call"> = async ($, e, next) => {
  const out = await next(e);
  if (laneDone(e, out)) wanted = REASON_LANE;
  const state = e.agentId ? agents.get(e.agentId) : undefined;
  if (!state || out.deny !== undefined) return out;
  const type = (await $.agent.list()).find((row) => row.id === e.agentId)?.type;
  const note = reportNote(state, type);
  return note ? { ...out, context: [...(out.context ?? []), note] } : out;
};

/** Starts the handoff of `/handoff`: names the file in the skill text and expects the file at the next `turn.complete`. */
export const onSkill: Handler<"skill.prompt"> = async ($, e, next) => {
  const out = await next(e);
  if (parseHandover(options["mainHandover"]) === "off") return out;
  const path = await runBin($, "dotclaude-handoff", ["path"]);
  if (!path.ok) return out;
  pending = { file: path.text };
  return {
    ...out,
    text: `${out.text}\n\nThe handoff file is \`${path.text}\`.`,
  };
};

/** Clears the session and submits the resume prompt when the file exists. */
const resume = async ($: EngineInterface, file: string): Promise<void> => {
  const newest = await runBin($, "dotclaude-handoff", ["newest"]);
  if (!newest.ok || newest.text !== file) return;
  const next = await runBin($, "dotclaude-spec", ["next"]);
  await $.command.run({ command: "clear" });
  await $.prompt.submit({ text: resumeText(file, next.ok ? next.text : "") });
};

/** The trigger that fired for the main session, or undefined. */
const triggerOf = async ($: EngineInterface): Promise<string | undefined> => {
  if (wanted) return wanted;
  const { context } = await $.session.usage();
  return overContext(context.percent, CONTEXT_PERCENT)
    ? reasonContext(context.percent ?? 0)
    : undefined;
};

/** Runs the handoff at the end of a turn of the main session. */
export const onTurnComplete: Handler<"turn.complete"> = async ($, e, next) => {
  const out = await next(e);
  if (e.agentId) return out;
  const mode = parseHandover(options["mainHandover"]);
  if (pending) {
    const { file } = pending;
    pending = undefined;
    wanted = undefined;
    hinted = false;
    await resume($, file);
    return out;
  }
  if (mode === "off") return out;
  const reason = await triggerOf($);
  if (!reason) {
    hinted = false;
    return out;
  }
  if (mode === "manual") {
    wanted = undefined;
    if (hinted) return out;
    hinted = true;
    return { ...out, text: `${out.text}\n\n${manualHint(reason)}` };
  }
  const path = await runBin($, "dotclaude-handoff", ["path"]);
  if (!path.ok) return out;
  pending = { file: path.text };
  wanted = undefined;
  await $.prompt.submit({ text: writePrompt(path.text) });
  return out;
};
